MM.mnemo[14] = {"cards":[{"id":"ko-k3-0264","w":"좋아하다","cs":"mít rád; líbit se","en":"to like","p":"v","o":"k","ex":"이 노래는 제가 좋아하는 노래예요.","exc":"Tahle píseň je píseň, kterou mám rád. (는 → téma; 가 → 1. pád; -는 → přívlastek)","h":"좋아 = dobře (ČO-A ≈ ČAU): „Čau, mám tě rád!“","m":"Sloveso s 4. pádem (영화를 좋아해요 = mám rád filmy). Pozor na rozdíl oproti přídavnému jménu 좋다 (být dobrý), které se pojí s 1. pádem (영화가 좋아요).","tv":["좋아해요"]},{"id":"ko-k3-0265","w":"불다","cs":"foukat; vát","en":"to blow","p":"v","o":"k","rz":["불다 → 부는","foukat → foukající (-는 → přívlastek, ㄹ vypadává)"],"h":"PUL ≈ PUFF: pufff – fouká vítr.","m":"Nepravidelné časování ㄹ: před ㄴ, ㅂ, ㅅ vypadává ㄹ, proto 부는 바람 (foukající vítr). Nejčastější spojení: 바람이 불다 = fouká vítr.","tv":["불어요"],"irr":"ㄹ (odpadá)"},{"id":"ko-k3-0266","w":"알다","cs":"vědět; znát","en":"to know","p":"v","o":"k","ex":"저기 있는 사람, 아는 사람이에요?","exc":"Ten člověk tamhle, je to někdo, koho znáš? (는 → téma; -는 → přívlastek)","h":"AL ≈ ALBERT: Albert Einstein všechno ví. Opak 모르다 (MOR).","m":"Nepravidelné časování ㄹ: před ㄴ vypadává ㄹ, takže ‚známý člověk‘ je 아는 사람 (ne 알는). Opak 모르다 (nevědět, neznat).","tv":["알아요"],"irr":"ㄹ (odpadá)"},{"id":"ko-k3-0267","w":"일하다","cs":"pracovat","en":"to work","p":"v","o":"k","rz":["일하다 → 일하는","pracovat → pracující (-는 → přívlastek)"],"h":"IL ≈ ILONA: Ilona pořád pracuje. 일 = práce.","m":"Základ 일 (práce, záležitost) + 하다 (dělat) = pracovat. Kdo pracuje, je 일하는 사람; pracoviště je 일터 nebo 직장.","tv":["일해요"]},{"id":"ko-k3-0268","w":"노래","cs":"píseň; písnička; zpěv","en":"song","p":"n","o":"k","ex":"이 노래는 제가 좋아하는 노래예요.","exc":"Tahle píseň je píseň, kterou mám rád. (는 → téma; 가 → 1. pád; -는 → přívlastek)","h":"NO-RE ≈ NORA: liška zpívá v noře písničku.","m":"Častá spojení: 노래를 부르다 / 노래하다 (zpívat píseň), 노래를 듣다 (poslouchat písničku), 노래방 (karaoke pokoj)."},{"id":"ko-k3-0269","w":"가수","cs":"zpěvák; zpěvačka","en":"singer","p":"n","o":"s","ex":"요즘 좋아하는 가수는 누구예요?","exc":"Kterého zpěváka máš v poslední době rád? (-는 → přívlastek; 는 → téma)","h":"KA-SU ≈ KAZETA: kazeta tvého oblíbeného zpěváka.","m":"歌 píseň, zpívat + 手 ruka (odborník, člověk) = člověk od zpěvu, tedy zpěvák. 手 ve významu ‚člověk/mistr‘ je i v 운전수 (řidič) nebo 선수 (sportovec).","r":["ga-歌","su-手"]},{"id":"ko-k3-0270","w":"외국어","cs":"cizí jazyk","en":"foreign language","p":"n","o":"s","ex":"요즘 공부하고 있는 외국어는 일본어예요.","exc":"Cizí jazyk, který se teď učím, je japonština.","h":"외국 = cizina (WE-GUK ≈ VEN, KUK!) + 어 = jazyk.","m":"外 cizí + 國 země + 語 jazyk = jazyk cizí země. 외국인 = cizinec.","r":["oe-外","guk-國","eo-語"]},{"id":"ko-k3-0271","w":"일본어","cs":"japonština","en":"Japanese (language)","p":"n","o":"s","ex":"요즘 공부하고 있는 외국어는 일본어예요.","exc":"Cizí jazyk, který se v poslední době učím, je japonština. (-고 있다 → právě dělat; -는 → přívlastek; 는 → téma)","h":"일본 = Japonsko (IL-PON ≈ NIPPON, jak Japonci říkají Japonsku) + 어 = jazyk.","m":"日 slunce, den + 本 základ, původ + 語 jazyk = jazyk země vycházejícího slunce, tedy japonština. 語 jako v 한국어 (korejština) nebo 영어 (angličtina).","r":["il-日","bon-本","eo-語"]},{"id":"ko-k3-0272","w":"카페","cs":"kavárna","en":"café","p":"n","o":"e","ex":"자주 가는 카페 있어요?","exc":"Je nějaká kavárna, kam chodíš často? (-는 → přívlastek)","h":"Z francouzštiny café.","m":"Výpůjčka z anglického/francouzského café. V Koreji jsou kavárny na každém rohu a často slouží jako místo ke studiu nebo práci."},{"id":"ko-k3-0273","w":"날","cs":"den","en":"day","p":"n","o":"k","ex":"눈이 오는 날에는 영화 보고 싶어요.","exc":"Ve dny, kdy sněží, se chci dívat na film. (이 → 1. pád; -는 → přívlastek; 에 → kdy)","h":"NAL ≈ NÁLADA: každý den jiná nálada.","m":"Ryze korejské slovo pro ‚den‘ (často s přívlastkem: 좋은 날 = krásný den, 비 오는 날 = deštivý den). Sinokorejský protějšek při počítání dnů je 일 (日)."},{"id":"ko-k3-0274","w":"옷 가게","cs":"obchod s oblečením","en":"clothing store","p":"f","o":"k","ex":"자주 가는 옷 가게가 있어요?","exc":"Máš nějaký obchod s oblečením, kam často chodíš? (-는 → přívlastek; 가 → 1. pád)","h":"OT ≈ OTOČ SE: otočíš se v novém oblečení před zrcadlem v obchodě (가게).","m":"Složené z 옷 (oblečení) + 가게 (obchod, krámek). Stejným způsobem se tvoří další názvy obchodů, např. 꽃가게 (květinářství) nebo 빵가게 (pekařství)."},{"id":"ko-k3-0275","w":"음식","cs":"jídlo; pokrm","en":"food","p":"n","o":"s","ex":"자주 먹는 한국 음식 있어요?","exc":"Je nějaké korejské jídlo, které jíš často? (-는 → přívlastek)","h":"ŮM-ŠIK ≈ UMÍŠ ŠIKOVNĚ: umíš šikovně uvařit jídlo.","m":"飮 pít + 食 jíst = pití a jídlo, tedy jídlo nebo pokrm. 食 jako v 식당 (restaurace) nebo 간식 (svačina).","r":["eum-飮","sik-食"]},{"id":"ko-k3-0276","w":"자주","cs":"často","en":"often","p":"o","o":"k","ex":"자주 가는 카페 있어요?","exc":"Je nějaká kavárna, kam chodíš často? (-는 → přívlastek)","h":"ČA-DŽU ≈ ČAJ, DŽUS: často pije čaj a džus.","m":"Stojí přímo před slovesem (자주 가다 = často chodit, 자주 만나다 = často se vídat). Opak 가끔 (občas, zřídka)."}],"gram":{"id":"ko-k3-g14","w":"-는 + 명사","en":"Making Adjectives (Part 2)","cs":"přívlastkový tvar dějových sloves (který / jenž…)","vy":"Koncovka -는 připojuje dějové sloveso přímo před podstatné jméno a vytváří přívlastek či vedlejší větu vztažnou v přítomném čase (‚člověk, který zpívá‘, ‚kniha, kterou mám rád‘). Připojuje se ke kmeni bez ohledu na to, zda končí samohláskou, nebo souhláskou, pouze kmeny končící na ㄹ toto ㄹ před -는 ztrácejí (열다 → 여는, 알다 → 아는). Stejnou koncovku -는 přibírají i slova končící na 있다 a 없다 (např. 있는, 맛있는).","m":"U dějových sloves rozhoduje čas: -는 + podstatné jméno znamená přítomnost (먹는 음식 = jídlo, které jím), zatímco -(으)ㄴ znamená minulost (먹은 음식 = jídlo, které jsem snědl). Pozor také na částice ve vedlejší větě: 민지가 좋아하는 사람 = člověk, kterého má ráda Mindži; 민지를 좋아하는 사람 = člověk, který má rád Mindži.","s":[["노래하는 사람","člověk, který zpívá (노래하다 → 노래하는)"],["좋아하는 책","kniha, kterou mám rád / oblíbená kniha"],["가는 · 자는 · 여는 · 부는","jdoucí · spící · otevírající · foukající (u kmenů na ㄹ odpadá ㄹ: 열다 → 여는, 불다 → 부는)"],["제가 안 좋아하는 책","kniha, kterou nemám rád"],["민지가 좋아하는 사람","člověk, kterého má ráda Mindži"],["민지를 좋아하는 사람","člověk, který má rád Mindži"],["이 노래는 제가 좋아하는 노래예요.","Tahle písnička je písnička, kterou mám rád."],["자주 먹는 한국 음식 있어요?","Je nějaké korejské jídlo, které jíš často?"],["자주 가는 카페 있어요?","Je nějaká kavárna, kam chodíš často?"],["요즘 좋아하는 가수는 누구예요?","Jakého zpěváka máš v poslední době rád?"],["요즘 공부하고 있는 외국어는 일본어예요.","Cizí jazyk, který se teď učím, je japonština."],["눈이 오는 날에는 영화 보고 싶어요.","Ve dnech, kdy sněží, se chci dívat na film."],["저기 있는 사람, 아는 사람이에요?","Ten člověk tamhle, to je někdo, koho znáš?"],["배고픈 사람 (있어요)?","Má někdo hlad? (Doslova: je tu někdo hladový?)"],["자주 가는 옷 가게가 있어요?","Máš nějaký obchod s oblečením, kam často chodíš?"],["아는 사람 · 모르는 사람","známý (člověk, kterého znáš) · neznámý (člověk, kterého neznáš)"],["공부하고 있는 학생들","studenti, kteří se učí"],["저 소파 위에서 자고 있는 사람 누구예요?","Kdo je ten člověk, co spí tamhle na pohovce?"]]}};
